	uint32_t at = 5u;
	uint32_t n  = 0u;

	while (n < total) {
		situ_view_t element;
		uint32_t    size;

		if (at >= view.limit) {
			return 0;
		}
		if (situ_view_sub(view, at, situ_remaining_u32(view.limit, at), &element)
				!= SITU_OK) {
			return 0;
		}
		size = fzn_reconcile_wire_fzn_reconcile_object_extent(element);
		if (size == 0u) {
			return 0;
		}
		if (size > situ_remaining_u32(view.limit, at)) {
			return 0;
		}
		at = at + size;
		n  = n + 1u;
	}
	return 1;
