/** How many bytes a whole `fzn_reconcile_objects` needs, given `have` of them.
 *
 * SITU_OK            a complete one is present; *need is its length
 * SITU_ERR_TRUNCATED not yet; *need is a lower bound on the total
 *
 * For framing a stream: read, ask, read the difference, ask again. The
 * length fields are read only once the bytes holding them have arrived,
 * which is the case every hand-written version of this gets wrong.
 */
static inline situ_err_t fzn_reconcile_wire_fzn_reconcile_objects_required(const uint8_t *data, uint32_t have, uint32_t *need)
{
	uint32_t at = 5u;
	uint32_t pos = 5u;
	situ_view_t view;

	/* A view over what has arrived, so every length expression below
	 * reads through the same bounds the accessors do. */
	view.base       = (uint8_t *)(uintptr_t)(const void *)data;
	view.limit      = have;
	view.generation = 0u;
	view.owner      = NULL;

	/* fzn_reconcile_objects.objects: reading its length means reading bytes that
	 * have to be here first. */
	if (have < 5u) {
		*need = at;
		return SITU_ERR_TRUNCATED;
	}

	/* fzn_reconcile_objects.objects: a run of `fzn_reconcile_object`, framed one element at
	 * a time. The walk the accessors use stops at the end of the bytes
	 * as readily as at the end of the run; this asks each element whether
	 * it is whole, which is the same question one level down. */
	{
		uint32_t n = 0u;
		for (;;) {
			uint32_t   part;
			situ_err_t e;

			if (n >= situ_nonneg_u32(situ_leaf_u64(situ_get_be16(situ_base(view) + 3u)))) {
				break;
			}
			if (have < pos) {
				/* Not one byte of this element yet, and the count
				 * is read: each element still owed is at least its
				 * floor (26.946). */
				*need = situ_need_u32(at,
				        situ_need_mul_u32(situ_nonneg_u32(situ_leaf_u64(situ_get_be16(situ_base(view) + 3u))) - n, 2u));
				return SITU_ERR_TRUNCATED;
			}
			e = fzn_reconcile_wire_fzn_reconcile_object_required(data + pos, situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				/* The element is short, so its own lower bound is part of
				 * this run's -- and so is a minimum for each element the
				 * count still promises after it. That minimum is the
				 * STRUCTURAL one, every value constraint ignored, because
				 * it has to agree with what each of those elements will
				 * itself report once reached -- FZN_RECONCILE_WIRE_FZN_RECONCILE_OBJECT_SIZE_MIN is derived from
				 * the constraints and made this total fall as bytes arrived
				 * (26.724). */
				*need = situ_need_u32(at, part);
				*need = situ_need_u32(*need, situ_need_mul_u32(situ_nonneg_u32(situ_leaf_u64(situ_get_be16(situ_base(view) + 3u))) - n - 1u, 2u));
				return SITU_ERR_TRUNCATED;
			}
			at  = situ_need_u32(at, part);
			pos = situ_need_u32(pos, part);
			n = n + 1u;
		}
	}

	*need = at;
	return have >= at ? SITU_OK : SITU_ERR_TRUNCATED;
}

